/// Build a tonic `Endpoint` with mandatory TLS from any address form.
///
/// Normalises `http://host:port` → `https://host:port` (callers throughout the
/// codebase use `http://` URLs in env vars; TLS is still applied via
/// `tls_config`, but an `https` scheme is the canonical form). `unix:` and
/// `https:` endpoints are passed through. The returned endpoint has
/// [`client_tls_config`] applied — callers add timeouts / connectors as needed.
pub fn tls_endpoint(address: &str) -> Result<Endpoint> {
    let normalised = if let Some(rest) = address.strip_prefix("http://") {
        format!("https://{rest}")
    } else if address.starts_with("https://") || address.starts_with("unix:") {
        address.to_string()
    } else {
        // Bare host:port — prefix https://
        format!("https://{address}")
    };
    let endpoint = Endpoint::from_shared(normalised)
        .map_err(|e| anyhow::anyhow!("invalid gRPC endpoint '{address}': {e}"))?;
    endpoint
        .tls_config(client_tls_config())
        .map_err(|e| anyhow::anyhow!("TLS config for '{address}': {e}"))
}

