//! Shared tonic `Channel` connector — TLS mandatory on all gRPC traffic.
//!
//! Supports two endpoint forms so the same `ZEROCLAW_GRPC` value works in dev
//! and in production:
//!   - TCP:  `https://host:port`           — local dev / gRPC-Web
//!   - UDS:  `unix:/run/ghostbridge/container.sock`
//!
//! Production is the Unix-socket form: the assistant container has no IP, so the
//! console reaches the op-grpc-bridge over `/run/ghostbridge/container.sock`
//! (native gRPC + reflection). `tonic::transport::Endpoint::from_shared` only
//! dials TCP authorities, so the `unix:` form is wired through
//! `connect_with_connector` with a `UnixStream` dialer.
//!
//! TLS: the bridge presents the real Let's Encrypt wildcard cert for
//! `*.ghostbridge.tech`. Clients verify it with webpki roots and a
//! `domain_name` override (`GHOSTBRIDGE_TLS_DOMAIN`, default
//! `bridge.ghostbridge.tech`) so dialing by IP or Unix socket still validates.

use anyhow::{Context, Result};
use hyper_util::rt::TokioIo;
use tokio::net::UnixStream;
use tonic::transport::{Channel, ClientTlsConfig, Endpoint, Uri};
use tower::service_fn;

/// TLS verification domain — matches the `*.ghostbridge.tech` cert SAN.
fn tls_domain() -> String {
    std::env::var("GHOSTBRIDGE_TLS_DOMAIN")
        .unwrap_or_else(|_| "bridge.ghostbridge.tech".to_string())
}

/// Client TLS config — webpki roots + domain_name override for IP/UDS dialing.
fn client_tls_config() -> ClientTlsConfig {
    ClientTlsConfig::new()
        .with_webpki_roots()
        .domain_name(tls_domain())
}

