/// Open a tonic `Channel` to either a `unix:` socket or a TCP `https://` endpoint.
/// TLS is mandatory on both paths.
pub async fn connect_channel(endpoint: &str) -> Result<Channel> {
    if let Some(path) = unix_socket_path(endpoint) {
        // The HTTP authority below is a placeholder required by tonic; the
        // connector ignores it and dials the Unix socket instead. TLS is
        // applied so the bridge's LE cert is verified (domain_name override).
        let channel = Endpoint::try_from("http://[::]:50051")
            .context("placeholder URI for Unix-socket endpoint")?
            .tls_config(client_tls_config())
            .context("TLS config for Unix-socket gRPC")?
            .connect_with_connector(service_fn(move |_: Uri| {
                let path = path.clone();
                async move { Ok::<_, std::io::Error>(TokioIo::new(UnixStream::connect(path).await?)) }
            }))
            .await
            .with_context(|| format!("connecting gRPC over Unix socket: {endpoint}"))?;
        Ok(channel)
    } else {
        // TCP — normalise http→https, apply TLS.
        let https_addr = if let Some(rest) = endpoint.strip_prefix("http://") {
            format!("https://{rest}")
        } else if !endpoint.starts_with("https://") {
            format!("https://{endpoint}")
        } else {
            endpoint.to_string()
        };
        let channel = Endpoint::from_shared(https_addr)
            .with_context(|| format!("invalid gRPC endpoint: {endpoint}"))?
            .tls_config(client_tls_config())
            .with_context(|| format!("TLS config for: {endpoint}"))?
            .connect()
            .await
            .with_context(|| format!("connecting gRPC over TCP: {endpoint}"))?;
        Ok(channel)
    }
}

