/// Extract the base domain from a subdomain string. nextdns `rewrite` matches
/// the domain and all its subdomains, so we collapse to the registrable base.
///   `qdrant.ghostbridge.tech` → `ghostbridge.tech`
///   `*.ghostbridge.tech`      → `ghostbridge.tech`
///   `mcp.internal`            → `mcp.internal`
fn base_domain(subdomain: &str) -> String {
    let trimmed = subdomain.trim_start_matches("*.");
    let labels: Vec<&str> = trimmed.split('.').collect();
    match labels.len() {
        0 => String::new(),
        1 => labels[0].to_string(),
        2 => trimmed.to_string(),
        _ => {
            // Last two labels (covers .tech, .com, .internal, etc.)
            labels[labels.len() - 2..].join(".")
        }
    }
}

/// Derive the nextdns rewrite set from the registry: every unique base domain
/// from all routable entries' subdomains → bridge ingress IP. Also includes
/// `3tched.com` (the hypervisor domain, from the existing nextdns forwarder)
/// so assistant.3tched.com / mail.3tched.com resolve through the bridge.
fn derive_nextdns_rewrites(registry: &SubidRegistry) -> NextdnsRewrites {
    let ip = ingress_ip();
    let mut domains: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();

    for entry in &registry.entries {
        for sd in &entry.subdomains {
            let base = base_domain(sd);
            if !base.is_empty() {
                domains.insert(base);
            }
        }
    }

    // 3tched.com is the hypervisor domain — not in the subid registry (it's the
    // host, not a container service) but must resolve through the bridge too.
    domains.insert("3tched.com".to_string());

    let rewrites: Vec<NextdnsRewrite> = domains
        .iter()
        .map(|d| NextdnsRewrite {
            domain: d.clone(),
            ip: ip.clone(),
        })
        .collect();

    NextdnsRewrites {
        version: 1,
        ingress_ip: ip,
        rewrites,
    }
}

/// Write the nextdns config file with rewrite directives (replacing the stale
/// dnsmasq forwarders). The profile ID comes from `NEXTDNS_PROFILE` env (sourced
/// from `.bash_secrets` by the s6 oneshot). The netmaker mesh forwarder is
/// preserved (it's a real external DNS, not a local service).
fn write_nextdns_config(rewrites: &NextdnsRewrites) -> Result<()> {
    let profile = nextdns_profile();
    let mut buf = String::new();

    if !profile.is_empty() {
        buf.push_str(&format!("profile {profile}\n"));
    }
    buf.push_str("device-name Ghostbridge-Incus\n");
    buf.push_str("report-client-info on\n");
    buf.push_str("hardened-privacy off\n");
    buf.push_str("cache-size 10MB\n");
    buf.push_str("max-ttl 5s\n");
    buf.push_str("listen localhost:53\n");
    buf.push('\n');

    // Rewrites — all owned domains → bridge ingress (xray → grpc-bridge).
    for rw in &rewrites.rewrites {
        buf.push_str(&format!("rewrite {}={}\n", rw.domain, rw.ip));
    }
    buf.push('\n');

    // Netmaker mesh DNS — real external forwarder, not a local service.
    buf.push_str("forwarder netmaker.cloud=100.90.37.2:53\n");

    let tmp = format!("{NEXTDNS_CONFIG}.tmp");
    let mut f =
        fs::File::create(&tmp).with_context(|| format!("create nextdns config tmp: {tmp}"))?;
    f.write_all(buf.as_bytes())
        .with_context(|| "write nextdns config tmp")?;
    f.sync_data().with_context(|| "sync nextdns config tmp")?;
    fs::rename(&tmp, NEXTDNS_CONFIG)
        .with_context(|| format!("rename nextdns config {tmp} → {NEXTDNS_CONFIG}"))?;

    info!(path = NEXTDNS_CONFIG, "Gemma wrote nextdns config (rewrites → {})", rewrites.ingress_ip);
    Ok(())
}

