        .with_context(|| format!("rename nextdns config {tmp} → {NEXTDNS_CONFIG}"))?;

    info!(path = NEXTDNS_CONFIG, "Gemma wrote nextdns config (owned domains → /etc/hosts → {})", rewrites.ingress_ip);
    Ok(())
}

/// Write a managed section into `/etc/hosts` mapping every owned subdomain to
/// the bridge ingress IP. nextdns checks `/etc/hosts` before forwarders
/// (`use-hosts on`), so the owned domains resolve locally to the bridge without
/// touching dnsmasq. The section is delimited by `# BEGIN/END GEMMA-DNS` markers
/// so re-runs are idempotent — only the managed section is replaced.
fn write_hosts_file(rewrites: &NextdnsRewrites) -> Result<()> {
    const HOSTS_PATH: &str = "/etc/hosts";
    const BEGIN_MARKER: &str = "# BEGIN GEMMA-DNS -- managed by op-gemma, do not edit";
    const END_MARKER: &str = "# END GEMMA-DNS";

    let ip = &rewrites.ingress_ip;
    let mut section = String::new();
    section.push_str(&format!("{BEGIN_MARKER}\n"));
    for rw in &rewrites.rewrites {
        // nextdns hosts lookup matches exact names, not wildcards. Expand
        // wildcard base domains to the explicit subdomains from the registry.
        section.push_str(&format!("{ip}\t{}\n", rw.domain));
    }
    section.push_str(&format!("{END_MARKER}\n"));

    let existing = fs::read_to_string(HOSTS_PATH).unwrap_or_default();

    // Remove any existing managed section, then append the new one.
    let cleaned = remove_managed_section(&existing, BEGIN_MARKER, END_MARKER);
    let updated = format!("{}\n{}", cleaned.trim_end(), section);

    let tmp = format!("{HOSTS_PATH}.gemma.tmp");
    fs::write(&tmp, updated.as_bytes())
        .with_context(|| format!("write hosts tmp: {tmp}"))?;
    fs::rename(&tmp, HOSTS_PATH)
        .with_context(|| format!("rename hosts {tmp} → {HOSTS_PATH}"))?;

    info!(
        path = HOSTS_PATH,
        entries = rewrites.rewrites.len(),
        ip = %ip,
        "Gemma wrote /etc/hosts managed section (owned domains → bridge)"
    );
    Ok(())
}

/// Remove text between begin/end markers (inclusive) from a string.
fn remove_managed_section(input: &str, begin: &str, end: &str) -> String {
    let mut result = String::with_capacity(input.len());
    let mut in_section = false;
    for line in input.lines() {
        if line.trim_start().starts_with(begin) {
            in_section = true;
            continue;
        }
        if in_section && line.trim_start().starts_with(end) {
            in_section = false;
            continue;
        }
        if !in_section {
            result.push_str(line);
            result.push('\n');
        }
    }
    result
}

