//! Gemma — the subid → tag → OpenFlow + xray routing brain.
//!
//! Reads the canonical subid registry from `/etc/ghostbridge/subid-registry.json`
//! and writes two tmpfs artifacts:
//!   - `/dev/shm/xray-routes.json`    — routes for the op-identity-shuttle
//!   - `/dev/shm/openflow-routes.json` — rules for the OpenFlow controller
//!
//! Per AGENTS.md §4: D-Bus is the control plane; Gemma is a host service that
//! produces structured state, not a CLI bypass. It never shells out to network
//! tools. OpenFlow rules may be applied via D-Bus by a separate controller.

mod ollama;
mod ui_gallery;

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::io::Write;
use std::path::Path;
use tracing::{info, warn};

const SUBID_REGISTRY: &str = "/etc/ghostbridge/subid-registry.json";
const XRAY_ROUTES: &str = "/dev/shm/xray-routes.json";
const OPENFLOW_ROUTES: &str = "/dev/shm/openflow-routes.json";
const NEXTDNS_REWRITES: &str = "/dev/shm/nextdns-rewrites.json";
const NEXTDNS_CONFIG: &str = "/dev/shm/nextdns-gemma.conf";

/// Bridge ingress IP — where xray fronts the tonic-web gRPC-bridge. All owned
/// subdomains resolve here. Overridable via `GHOSTBRIDGE_INGRESS_IP` (no
/// hardcoded IP in the binary).
fn ingress_ip() -> String {
    std::env::var("GHOSTBRIDGE_INGRESS_IP").unwrap_or_else(|_| "10.0.0.2".to_string())
}

/// NextDNS profile ID — sourced from `.bash_secrets` via env, never inlined.
fn nextdns_profile() -> String {
    std::env::var("NEXTDNS_PROFILE").unwrap_or_else(|_| {
        warn!("NEXTDNS_PROFILE not set; nextdns config will lack a profile line");
        String::new()
    })
}

