//! Axum HTTP/gRPC-Web host for the zeroclaw plugin schema.
//!
//! Serves the plugin-owned schema JSON on:
//!   - native gRPC over Unix socket `/run/opdbus/zeroclaw-grpc.sock`
//!   - HTTP/1.1 + gRPC-Web on TCP `0.0.0.0:8090` (configurable via D-Bus)
//!
//! The schema itself is never generated here; it is read from
//! `/dev/shm/opdbus/schemas/zeroclaw.json` written by the zeroclaw plugin.

use std::net::SocketAddr;
use std::path::PathBuf;
use std::pin::Pin;
use std::sync::Arc;

use async_stream::stream;
use axum::Router;
use tokio::sync::mpsc;
use tonic::{Request as TonicRequest, Response as TonicResponse, Status};
use tower_http::cors::{Any, CorsLayer};
use tracing::info;

use crate::dbus_object::{register_zeroclaw_host_object, ZeroclawAxumHostObject};
use crate::grpc_server::OperationGrpcServer;
use crate::mutation_engine::MutationEngine;
use crate::schema_loader::{SchemaLoader, SchemaReloadEvent};
use crate::tracing::{GhostbridgeTraceLayer, TraceContext};

use crate::grpc_server::build_operation_routes;
use crate::proto::zeroclaw::{
    zeroclaw_service_server::{ZeroclawService, ZeroclawServiceServer},
    GetSchemaRequest, SchemaEvent, SchemaResponse, WatchSchemaRequest,
};

const DEFAULT_UNIX_SOCKET: &str = "/run/opdbus/zeroclaw-grpc.sock";
const DEFAULT_BIND_ADDR: &str = "0.0.0.0:8090";
const DEFAULT_SCHEMA_PATH: &str = "/dev/shm/opdbus/schemas/zeroclaw.json";

/// Runtime configuration for the zeroclaw Axum host.
#[derive(Clone, Debug)]
pub struct ServerConfig {
    pub schema_path: PathBuf,
    pub unix_socket: PathBuf,
    pub bind_addr: String,
}

impl Default for ServerConfig {
    fn default() -> Self {
        Self {
            schema_path: PathBuf::from(DEFAULT_SCHEMA_PATH),
            unix_socket: PathBuf::from(DEFAULT_UNIX_SOCKET),
            bind_addr: DEFAULT_BIND_ADDR.to_string(),
        }
    }
}

impl ServerConfig {
    /// Load configuration from environment variables, falling back to defaults.
    pub fn from_env() -> Self {
        Self {
            schema_path: PathBuf::from(
                std::env::var("ZEROCLAW_SCHEMA_PATH")
                    .unwrap_or_else(|_| DEFAULT_SCHEMA_PATH.to_string()),
            ),
            unix_socket: PathBuf::from(
                std::env::var("ZEROCLAW_UNIX_SOCKET")
                    .unwrap_or_else(|_| DEFAULT_UNIX_SOCKET.to_string()),
            ),
            bind_addr: std::env::var("ZEROCLAW_BIND_ADDR")
                .unwrap_or_else(|_| DEFAULT_BIND_ADDR.to_string()),
        }
    }
}

/// Shared state for the gRPC service handlers.
#[derive(Clone)]
struct ZeroclawGrpcService {
    loader: Arc<SchemaLoader>,
}

#[tonic::async_trait]
impl ZeroclawService for ZeroclawGrpcService {
    type WatchSchemaStream =
        Pin<Box<dyn tokio_stream::Stream<Item = Result<SchemaEvent, Status>> + Send>>;

    async fn get_schema(
        &self,
        request: TonicRequest<GetSchemaRequest>,
    ) -> Result<TonicResponse<SchemaResponse>, Status> {
        let context = request
            .extensions()
            .get::<TraceContext>()
            .cloned()
            .unwrap_or_else(|| TraceContext::from_tonic_metadata(request.metadata()));

        let schema_json = self.loader.get().await.to_string();
        let mut response = TonicResponse::new(SchemaResponse {
            schema_json,
            trace_id: context.trace_id.clone(),
            footprint: context.footprint.clone(),
        });
        inject_trace_metadata(&mut response, &context);
        Ok(response)
    }

    async fn watch_schema(
        &self,
        _request: TonicRequest<WatchSchemaRequest>,
    ) -> Result<TonicResponse<Self::WatchSchemaStream>, Status> {
        let mut reload_rx = self.loader.reload_tx().subscribe();
        let loader = self.loader.clone();

        let initial = loader.get().await;
        let stream = stream! {
            yield Ok(SchemaEvent {
                schema_json: initial.to_string(),
                event_type: "initial".to_string(),
            });

            while let Ok(SchemaReloadEvent { event_type }) = reload_rx.recv().await {
                let schema_json = loader.get().await.to_string();
                yield Ok(SchemaEvent {
                    schema_json,
                    event_type,
                });
            }
        };

        Ok(TonicResponse::new(Box::pin(stream)))
    }
}

fn inject_trace_metadata<T>(response: &mut TonicResponse<T>, context: &TraceContext) {
    if let (Ok(trace_id), Ok(footprint)) = (context.trace_id.parse(), context.footprint.parse()) {
        response
            .metadata_mut()
            .insert("x-ghostbridge-trace-id", trace_id);
        response
            .metadata_mut()
            .insert("x-ghostbridge-footprint", footprint);
    }
}

/// Assemble the gRPC service set for the zeroclaw bridge.
///
/// The full backplane surface (StateSync, PluginService, DbusPassthrough,
/// OvsdbMirror, RuntimeMirror, EventChainService, ComponentRegistry, Mail,
/// Privacy, Registration, McpService, ChatService, reflection) comes from the
/// shared [`build_operation_routes`] — identical to what `run_grpc_server` mounts
/// on op-dbus :50051, so reflection never advertises an unmounted service. On top
/// of that the zeroclaw bridge adds its endpoint-specific `ZeroclawService`
/// (plugin-owned schema get/watch).
///
/// Every container shares this one surface over `container.sock`; the assistant
/// container is provisioned exactly like the others (its socket created via the
/// unix-socket plugin's createsocket through PluginService, not a raw Incus proxy
/// device).
fn build_routes(loader: Arc<SchemaLoader>, server: OperationGrpcServer) -> tonic::service::Routes {
    let zeroclaw_svc =
        tonic_web::enable(ZeroclawServiceServer::new(ZeroclawGrpcService { loader }));
    build_operation_routes(server).add_service(zeroclaw_svc)
}

/// Build the axum `Router` that serves the gRPC service over HTTP/gRPC-Web.
pub fn build_axum_app(loader: Arc<SchemaLoader>, server: OperationGrpcServer) -> Router {
    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
        .allow_headers(Any);

    build_routes(loader, server)
        .into_axum_router()
        .layer(cors)
        .layer(GhostbridgeTraceLayer::new())
}

/// Build the tonic `Routes` used for the native-gRPC Unix socket side.
fn build_tonic_routes(
    loader: Arc<SchemaLoader>,
    server: OperationGrpcServer,
) -> tonic::service::Routes {
    build_routes(loader, server)
}

/// Run the zeroclaw Axum host.
///
/// Returns only when both listeners exit (which should not happen under normal
/// operation).
pub async fn run_zeroclaw_server(config: ServerConfig) -> anyhow::Result<()> {
    let loader = Arc::new(SchemaLoader::new(&config.schema_path)?);

    // Channel for D-Bus-triggered rebind requests. Only `SchemaPath` changes are
    // applied live; `BindAddr` changes are recorded and honored on the next
    // restart.
    let (rebind_tx, mut rebind_rx) = mpsc::channel::<String>(4);

    // D-Bus object for runtime configuration.
    let dbus_object = ZeroclawAxumHostObject::new(loader.clone(), rebind_tx)?;
    let _dbus_connection = register_zeroclaw_host_object(dbus_object).await?;

    // SIGHUP reload watcher.
    let _sighup_handle = loader.clone().watch_sighup();

    // PluginService (PluginService.CallMethod) backed by the authoritative
    // MutationEngine. This is how createunixsocket is invoked: a CallMethod with
    // plugin_id="unix_socket" routes through MutationEngine.mutate →
    // UnixSocketPlugin::create_unix_socket. The sled identity is resolved as
    // the actor_id inside mutate when the caller omits it.
    let event_chain = Arc::new(tokio::sync::RwLock::new(op_state_store::EventChain::new(
        op_state_store::ChainConfig::default(),
    )));
    let ovsdb = Arc::new(op_network::rovs_proxy::OvsdbDbusClient::new());
    let nonnet = Arc::new(op_jsonrpc::nonnet::NonNetDb::new());
    let mutation_engine = Arc::new(MutationEngine::new(event_chain, ovsdb, nonnet));
    let operation_server = OperationGrpcServer::new(mutation_engine);
    // Attach the semantic shuttle for parity with run_grpc_server so
    // SearchSemanticTrace behaves identically on both endpoints (best-effort:
    // if Qdrant is unavailable the method returns failed_precondition).
    let operation_server = match op_cognitive_mcp::QdrantSemanticShuttle::new().await {
        Ok(shuttle) => operation_server.with_semantic_shuttle(Arc::new(shuttle)),
        Err(error) => {
            tracing::warn!(%error, "semantic shuttle unavailable; SearchSemanticTrace will return failed_precondition");
            operation_server
        }
    };

    // Unix socket listener for native gRPC.
    let unix_socket = config.unix_socket.clone();
    if let Some(parent) = unix_socket.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let _ = std::fs::remove_file(&unix_socket);
    let unix_listener = tokio::net::UnixListener::bind(&unix_socket)?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&unix_socket, std::fs::Permissions::from_mode(0o666))?;
    }
    info!(path = %unix_socket.display(), "zeroclaw native gRPC listening on Unix socket (TLS mandatory)");

    let unix_incoming = tokio_stream::wrappers::UnixListenerStream::new(unix_listener);

    // Mandatory TLS — the shared module loads the real LE wildcard cert for
    // *.ghostbridge.tech. Both the Unix socket and TCP listeners present it.
    let unix_tls =
        crate::tls::server_tls_config().map_err(|e| anyhow::anyhow!("zeroclaw Unix TLS: {e}"))?;
    let tcp_tls =
        crate::tls::server_tls_config().map_err(|e| anyhow::anyhow!("zeroclaw TCP TLS: {e}"))?;

    // accept_http1(true): tonic-web serves gRPC-Web over HTTP/1.1, which is what
    // browsers (and xray's tls-h1 fallback forwarding to this socket) speak. Without
    // it the socket is h2-only and rejects browser gRPC-Web. Matches the TCP side.
    let tonic_server = tonic::transport::Server::builder()
        .accept_http1(true)
        .tls_config(unix_tls)
        .map_err(|e| anyhow::anyhow!("zeroclaw Unix TLS config: {e}"))?
        .add_routes(build_tonic_routes(loader.clone(), operation_server.clone()))
        .serve_with_incoming(unix_incoming);

    // TCP listener for gRPC-Web (browsers / xray redirect). TLS mandatory.
    // Both listeners build from the shared `build_tonic_routes` so the service
    // surface is identical — the interceptor (in `build_operation_routes`)
    // enforces the zero-trust gate on both. CORS is applied here for browser
    // gRPC-Web clients.
    let bind_addr: SocketAddr = config.bind_addr.parse()?;
    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
        .allow_headers(Any);
    info!(addr = %bind_addr, "zeroclaw gRPC-Web listening on TCP (TLS mandatory)");

    let tcp_server = tonic::transport::Server::builder()
        .accept_http1(true)
        .tls_config(tcp_tls)
        .map_err(|e| anyhow::anyhow!("zeroclaw TCP TLS config: {e}"))?
        .layer(cors)
        .add_routes(build_tonic_routes(loader, operation_server))
        .serve(bind_addr);

    // Rebind task: when a new bind address is requested, restart the TCP server.
    // The current implementation starts the initial TCP server; subsequent
    // rebinds require a restart to keep the listener lifecycle simple and safe.
    let rebind_task = tokio::spawn(async move {
        while let Some(new_bind) = rebind_rx.recv().await {
            info!(new_bind = %new_bind, "D-Bus rebind request received; will be honored on next restart");
        }
    });

    let (unix_result, tcp_result) = tokio::join!(tonic_server, tcp_server);
    let _ = rebind_task.await;
    unix_result.map_err(|e| anyhow::anyhow!("Unix server error: {}", e))?;
    tcp_result.map_err(|e| anyhow::anyhow!("TCP server error: {}", e))
}

//! Shared tonic TLS material — mandatory on ALL gRPC traffic (every server and
//! every client). Borrows the real Let's Encrypt wildcard cert for
//! `*.ghostbridge.tech` (full chain, publicly trusted — NOT self-signed), the
//! same cert xray's TLS inbounds present. There is no plaintext gRPC surface.
//!
//! Reality (the xray decoy) is unrelated: it borrows `www.microsoft.com`'s
//! handshake and uses no local cert. This module is only the genuine LE cert.

use anyhow::{Context, Result};
use std::path::PathBuf;
use tonic::transport::{ClientTlsConfig, Endpoint, Identity, ServerTlsConfig};

/// Full-chain cert and key, overridable via env. Defaults to the xray LE cert.
const DEFAULT_CERT: &str = "/etc/ssl/xray/ghostbridge.tech.pem";
const DEFAULT_KEY: &str = "/etc/ssl/xray/ghostbridge.tech.key";

/// Verification name clients use when dialing the bridge by IP (or unix socket):
/// matches the cert's `*.ghostbridge.tech` SAN so TLS validates without the IP
/// being in the cert. Overridable via `GHOSTBRIDGE_TLS_DOMAIN`.
const DEFAULT_TLS_DOMAIN: &str = "bridge.ghostbridge.tech";

fn cert_path() -> PathBuf {
    std::env::var("GHOSTBRIDGE_TLS_CERT")
        .unwrap_or_else(|_| DEFAULT_CERT.to_string())
        .into()
}

fn key_path() -> PathBuf {
    std::env::var("GHOSTBRIDGE_TLS_KEY")
        .unwrap_or_else(|_| DEFAULT_KEY.to_string())
        .into()
}

pub fn tls_domain() -> String {
    std::env::var("GHOSTBRIDGE_TLS_DOMAIN").unwrap_or_else(|_| DEFAULT_TLS_DOMAIN.to_string())
}

/// Server identity (full chain + private key) for every tonic gRPC server.
pub fn server_identity() -> Result<Identity> {
    let cert = cert_path();
    let key = key_path();
    let cert_pem = std::fs::read(&cert).with_context(|| format!("read TLS cert {cert:?}"))?;
    let key_pem = std::fs::read(&key).with_context(|| format!("read TLS key {key:?}"))?;
    Ok(Identity::from_pem(cert_pem, key_pem))
}

/// `ServerTlsConfig` for every tonic gRPC server. Mandatory — callers must apply
/// this (no `Option`): there is no plaintext gRPC.
pub fn server_tls_config() -> Result<ServerTlsConfig> {
    Ok(ServerTlsConfig::new().identity(server_identity()?))
}

/// `ClientTlsConfig` for every tonic gRPC client. The LE cert is publicly
/// trusted, so bundled webpki roots verify it; `domain_name` lets clients dial
/// by IP/unix-socket and still validate the `*.ghostbridge.tech` cert.
pub fn client_tls_config() -> ClientTlsConfig {
    ClientTlsConfig::new()
        .with_webpki_roots()
        .domain_name(tls_domain())
}

/// Build a tonic `Endpoint` with mandatory TLS from any address form.
///
/// Normalises `http://host:port` → `https://host:port` (callers throughout the
/// codebase use `http://` URLs in env vars; TLS is still applied via
/// `tls_config`, but an `https` scheme is the canonical form). `unix:` and
/// `https:` endpoints are passed through. The returned endpoint has
/// [`client_tls_config`] applied — callers add timeouts / connectors as needed.
pub fn tls_endpoint(address: &str) -> Result<Endpoint> {
    let normalised = if let Some(rest) = address.strip_prefix("http://") {
        format!("https://{rest}")
    } else if address.starts_with("https://") || address.starts_with("unix:") {
        address.to_string()
    } else {
        // Bare host:port — prefix https://
        format!("https://{address}")
    };
    let endpoint = Endpoint::from_shared(normalised)
        .map_err(|e| anyhow::anyhow!("invalid gRPC endpoint '{address}': {e}"))?;
    endpoint
        .tls_config(client_tls_config())
        .map_err(|e| anyhow::anyhow!("TLS config for '{address}': {e}"))
}

