use std::sync::OnceLock;
use tonic::transport::{ClientTlsConfig, Endpoint, Identity, ServerTlsConfig};

/// Install the rustls crypto provider exactly once at process startup.
/// Both `ring` and `aws-lc-rs` features are enabled transitively (ring via
